+
+#[test]
+fn a_used_component_is_not_deleted_and_an_unused_one_is() {
+    let (w, mut h) = shop();
+    let Err(e) = DeleteDocumentComponent::new(&w, INSERT) else { panic!("the insert is in use") };
+    let msg = e.to_string();
